-- Course detail pages (as on ohsoed.co.uk/courses-details/...): topics and exam board for each level and subject.
alter table course_pages add column if not exists exam_board text;
do $$ declare sch uuid; lv uuid; sj uuid; begin
  select id into sch from schools where slug = 'ohsoed'; if sch is null then return; end if;
  select id into lv from levels where school_id = sch and name = 'KS3';
  select id into sj from subjects where school_id = sch and lower(name) = lower('English Language');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'English Language', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'ks3/english-language', '[{"title": "Transactional Writing", "text": "An introduction to writing for various genres, styles and transactional disciplines, learning to adapt purpose, audience and form for differing styles."}, {"title": "Nature Poetry", "text": "An introduction to analysing the language, structure and form of varying styles of nature poetry."}, {"title": "Prose Texts", "text": "An introduction to analysing plot, characterisation and language associated with a prose text within differing genres."}, {"title": "Descriptive Writing", "text": "An introduction to writing for various genres, styles and descriptive disciplines."}, {"title": "Narrative Writing", "text": "An introduction to writing in a narrative style within differing genres, learning how to structure and narrate a short story."}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'KS3';
  select id into sj from subjects where school_id = sch and lower(name) = lower('English Literature');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'English Literature', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'ks3/english-literature', '[{"title": "Phillip Pullman: Frankenstein", "text": "An introduction to analysing plot, characterisation and language associated with a gothic literature play text."}, {"title": "Greek Myths and Legends", "text": "An introduction to analysing plot, characterisation and language associated with Greek mythology texts."}, {"title": "Shakespeare: A midsummer Night’s Dream", "text": "An introduction to analysing the language, structure and form of a Shakespeare play."}, {"title": "Oliver Twist & Dickensian London", "text": "An introduction to analysing plot, characterisation and language associated with a classic literature text."}, {"title": "Sci-Fi Texts", "text": "An introduction to analysing the dramatic conventions, language and structure of a Sci-Fi text."}, {"title": "Animal Poetry", "text": "An introduction to analysing the language, structure and form of varying styles of poetry."}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'KS3';
  select id into sj from subjects where school_id = sch and lower(name) = lower('Geography');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'Geography', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'ks3/geography', '[{"title": "Tectonic Hazards", "text": "This course will introduce students to the fascinating and sometimes terrifying world of tectonic activity, which shapes our planet in countless ways. Tectonic hazards, such as earthquakes, volcanoes, and tsunamis, can cause immense destruction and loss of life, but they can also create stunning landscapes and provide valuable resources.Throughout this course, you will learn about the processes that cause tectonic activity and how they can lead to hazards. You will explore the different types of tectonic hazards and their effects on human communities and the environment. You will also study the methods used to monitor and predict tectonic activity, as well as the strategies that can be used to prepare for and respond to tectonic hazards"}, {"title": "Map Skills", "text": "This course is designed to introduce you to the essential concepts and techniques of map reading and interpretation. Throughout the course, you will learn how to read and interpret maps, including understanding symbols and scales, identifying different features, and understanding contour lines. You will also learn about different types of maps, such as topographic, political and weather maps, and how to use them for different purposes.In addition to map reading skills, you will also learn about different tools and technologies used in mapping, including GPS and satellite imagery. You will explore how these tools are used to create and update maps, and how they can be used to improve navigation and emergency responses."}, {"title": "Weather and Climate", "text": "In this course, we will be exploring the fascinating world of weather and climate. We will start by examining the basics of meteorology, including the different types of clouds, weather instruments, and how to read weather maps. Next, we will delve into the factors that influence climate, such as the greenhouse effect, ocean currents, and atmospheric circulation. We will also discuss how climate has changed over time, and what the potential consequences of climate change might be."}, {"title": "Extreme Environments", "text": "In this course, we will explore some of the most challenging and fascinating environments on our planet, including deserts, mountains and polar regions. Through engaging and interactive lessons, you will learn about the unique characteristics of these extreme environments and how plants, animals, and humans have adapted to survive in them. We will also investigate the impact of human activity on these environments and the importance of conservation efforts to protect them for future generations."}, {"title": "Population", "text": "Population is a fundamental concept in the study of geography. It refers to the total number of people living in a particular geographic area at a given time. This course will involve understanding the distribution, characteristics, and changes in human population across different regions of the world."}, {"title": "China", "text": "In this course, we will be exploring the rich and fascinating history, culture, geography, and society of this vast and diverse country. China is one of the world''s oldest and most influential civilizations, with a history that stretches back over 5,000 years. From the earliest dynasties to the modern era, China has played a key role in shaping world history, culture, and trade.Through this course, you will learn about the major events and figures that have shaped China''s past and present. You will also explore China''s diverse geography, from its vast deserts and towering mountains to its fertile river valleys and bustling coastal cities."}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'KS3';
  select id into sj from subjects where school_id = sch and lower(name) = lower('History');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'History', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'ks3/history', '[{"title": "The development of Church, state and society in Medieval Britain 1066-1509", "text": "- The Norman Conquest\n- The struggle between Church and crown\n- King John and the Magna Carta\n- Society, economy and culture in Medieval England\n- The Black Death and its social and economic impact\n- The Peasants’ Revolt"}, {"title": "The development of Church, state and society in Britain 1509-1745", "text": "- Renaissance and Reformation in Europe\n- The English Reformation and Counter Reformation (Henry VIII to Mary I)\n- The Elizabethan religious settlement and conflict with Catholics (including Scotland, Spain and Ireland)\n- The Stuarts and the English Civil War"}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'KS3';
  select id into sj from subjects where school_id = sch and lower(name) = lower('Maths');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'Maths', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'ks3/maths', '[{"title": "Graphs", "text": "An introduction to graphs, what they look like and why."}, {"title": "Ratio, Proportion and rates of change", "text": "Developing the key skills required to work on ratio and proportion problems."}, {"title": "Geometry and Measures", "text": "This course aims to broaden students'' understanding of some of the key skills required to succeed in geometry and measures."}, {"title": "Probability and Statistics", "text": "What are the chances of an events happening? How can we analyse data? This course offers an introduction to key probability and statistical skills."}, {"title": "Number", "text": "Making sure those all important number skills are up to scratch, including learning how to use and apply these skills in a problem solving context."}, {"title": "Algebra", "text": "Study of the essential algebra skills within a problem solving context."}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'KS3';
  select id into sj from subjects where school_id = sch and lower(name) = lower('Science');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'Science', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'ks3/science', '[{"title": "Living Organisms", "text": "An introduction to cells and organisation, including the skeletal and muscle systems, nutrition, digestion and gaseous exchange."}, {"title": "Reproduction and inheritance", "text": "An introduction to reproduction and genetics in humans and plants, including reproductive systems, menstrual cycle, gametes, fertilisation, gestation and birth."}, {"title": "Physical chemistry", "text": "An introduction to the properties of matter, atoms, elements, compounds and the periodic table."}, {"title": "Organic chemistry", "text": "An introduction to the composition and structure of the earth, rock cycles, the carbon cycle and composition of the atmosphere."}, {"title": "Forces", "text": "An introduction to motion, forces and pressure."}, {"title": "Energy", "text": "An introduction to energy stores, energy in the home and electricity."}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'Pre-GCSE';
  select id into sj from subjects where school_id = sch and lower(name) = lower('Business Studies');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'Business Studies', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'pre-gcse/business-studies', '[{"title": "Enterprise and entrepreneurship", "text": "- Intro to business\n- Dynamic nature of business\n- Invention and innovation\n- Enterprise and entrepreneurship\n- Risk and reward"}, {"title": "Spotting a business opportunity", "text": "- Added value\n- Customer needs\n- Primary and secondary research\n- Qualitative and quantitative data\n- Market segments and mapping"}, {"title": "Making the business effective", "text": "- Competitive environments\n- Product\n- Price\n- Promotion\n- Place"}, {"title": "Growing the business", "text": "- Growing the business\n- Financing growth\n- Ethics\n- Environment\n- Pressure groups"}, {"title": "Making operational decisions", "text": "- Methods of production\n- Tech and robots\n- Managing stock\n- Quality \n- Sales process"}, {"title": "Making human resource decisions", "text": "- Recruitment\n- Ways of working\n- Training and development\n- Remuneration\n- Motivation"}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
