  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'pre-gcse/english-language', '[{"title": "Non-fiction (Travel Texts)", "text": "An introduction to analysing the language, structure, purpose and form of non-fiction texts."}, {"title": "Transactional Writing (Travel Writing)", "text": "An introduction to writing for various genres, styles and transactional disciplines, learning to adapt purpose, audience and form for differing styles."}, {"title": "War Poetry", "text": "An introduction to analysing the language, structure and form of varying styles of war poetry."}, {"title": "Prose Texts", "text": "An introduction to analysing plot, characterisation and language associated with a prose text within differing genres."}, {"title": "Descriptive Writing", "text": "An introduction to writing for various genres, styles and descriptive disciplines."}, {"title": "Narrative Writing", "text": "An introduction to writing in a narrative style within differing genres, learning how to structure and narrate a short story."}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'Pre-GCSE';
  select id into sj from subjects where school_id = sch and lower(name) = lower('English Literature');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'English Literature', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'pre-gcse/english-literature', '[{"title": "Gothic Literature Texts", "text": "An introduction to analysing plot, characterisation and language associated with a gothic literature text."}, {"title": "Shakespeare: Romeo and Juliet", "text": "An introduction to analysing the language, structure and form of a Shakespeare play."}, {"title": "Dickens: A Christmas Carol", "text": "An introduction to analysing plot, characterisation and language associated with a classic literature text."}, {"title": "Mallatratt: The Woman In Black", "text": "An introduction to analysing plot, characterisation and dramatic conventions associated with playtexts."}, {"title": "George Orwell: Animal Farm", "text": "An introduction to analysing the literary concepts, language and structure of a contemporary text."}, {"title": "Poetry: Power & Conflict", "text": "An introduction to analysing the language, structure and form of varying styles of poetry."}]'::jsonb, null, true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'Pre-GCSE';
  select id into sj from subjects where school_id = sch and lower(name) = lower('Geography');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'Geography', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'pre-gcse/geography', '[{"title": "Rivers", "text": "In this unit, you will explore the intricacies of the global hydrological cycle, including drainage basins. You will delve into the physical processes that shape unique river landforms and examine detailed case studies of river management in both developed and developing countries."}, {"title": "Rural Environments", "text": "Throughout this unit, you will explore the distribution and distinct characteristics of rural environments, as well as human activities that take place within them. Additionally, you will examine the various changes that occur in contrasting rural environments and dive into detailed case studies of rural environments in both developed and developing/emerging countries."}, {"title": "Globalisation and Migration", "text": "Throughout this unit, you will gain insights into the dynamics of globalisation, including its defining characteristics and growth patterns. We''ll delve into the roles played by global institutions and transnational corporations in shaping the global economy. Additionally, we''ll examine the diverse impacts that globalisation has on societies and cultures around the world, with a particular focus on migration and tourism. Finally, we''ll explore different strategies for managing these impacts sustainably, so that we can promote a more equitable and just global community."}]'::jsonb, null, true)
