  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'pre-gcse/history', '[{"title": "Ideas, political power, industry and empire: Britain, 1745-1901", "text": "- The development of the British Empire with a depth study (for example, of India)\n- Britain’s transatlantic slave trade: its effects and its eventual abolition\n- Britain as the first industrial nation – the impact on society"}, {"title": "Challenges for Britain, Europe and the wider world 1901 to the present day", "text": "- Women’s suffrage \n- The First World War and the Peace Settlement \n- The Second World War\n- Weimar and Nazi Germany\n- The Holocaust"}]'::jsonb, null, true)
