  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'igcse/biology', '[{"title": "The nature and variety of living organisms", "text": "- Characteristics of living organisms \n- Variety of living organisms\n- Structures and functions in living organisms"}, {"title": "Level of organisation", "text": "- Cell structure\n- Biological molecules\n- Movement of substances into and out of cells\n- Nutrition\n- Respiration\n- Gas exchange\n- Transport\n- Excretion \n- Coordination and response\n- Reproduction and inheritance"}, {"title": "Reproduction", "text": "- Inheritance\n- Ecology and the environment"}, {"title": "The organism in the environment", "text": "- Feeding relationships\n- Cycles within ecosystems\n- Human influences on the environment"}, {"title": "Use of biological resources", "text": "- Food production\n- Selective breeding\n- Genetic modification (genetic engineering)\n- Cloning"}, {"title": "Revision", "text": "- Revision of all components of Edexcel iGCSE Biology Papers 1 & 2\n- Past Papers\n- Mock Exams"}]'::jsonb, null, true)
