  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'igcse/english-language', '[{"title": "Non-Fiction Anthology Texts", "text": "- Study of the contemporary non-fiction texts from Part 1 of the Pearson Edexcel International GCSE English Anthology.\n- Develop skills to analyse how writers use linguistic and structural devices to achieve their effects.\n- Explore links and connections between writers’ ideas and perspectives."}, {"title": "Transactional Writing", "text": "- Develop transactional writing skills for a variety of purposes and audiences.\n- Develop transactional writing skills to engage the reader.\n- Use spelling, punctuation and grammar accurately."}, {"title": "Poetry and Prose Anthology Texts", "text": "- Study of poetry and prose texts from Part 2 of the Pearson Edexcel International GCSE English Anthology.\n- Develop skills to analyse how writers use linguistic and structural devices to achieve their effects."}, {"title": "Imaginative Writing", "text": "- Develop imaginative writing skills for a variety of purposes and audiences.\n- Develop imaginative writing skills to engage the reader.\n- Use spelling, punctuation and grammar accurately."}, {"title": "Revision", "text": "- Revision of all components of Edexcel iGCSE English Paper 1 & 2\n- Past Papers\n- Mock Exam"}]'::jsonb, 'Edexcel', true)
