  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'igcse/english-literature', '[{"title": "Unseen and Anthology Poetry", "text": "- Explore how writers create meaning and effects in a range of seen and unseen poetry.\n- Develop skills to compare a range of poetry from the Pearson Edexcel IGCSE Anthology."}, {"title": "Modern Prose: Of Mice and Men", "text": "- Explore how writers create meaning and effects in a modern prose text. \n- Explore how contextual factors influence meanings and effects."}, {"title": "Modern Drama: J.B Priestley’s An Inspector Calls", "text": "- Develop skills to analyse how language, form, structure and contextual factors can be used to create meaning and effect in a modern play text.\n- Explore how contextual factors influence meanings and effects."}, {"title": "Literary Heritage Text: Shakespeare’s Macbeth", "text": "- Develop skills to analyse how language, form, structure and contextual factors can be used to create meaning and effect in a Shakespeare text\n- Explore how contextual factors influence meanings and effects."}, {"title": "Revision", "text": "- Revision of all components of Edexcel iGCSE English Literature Papers 1 & 2\n- Past Papers\n- Mock Exams"}]'::jsonb, null, true)
