  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'igcse/business-studies', '[{"title": "Year 1 : Business activity and influences of business", "text": "Students study objectives of a business, changing business environments and the criteria for judging success. \n1.1 - Business objectives\n1.2 - Types of organisations\n1.3 - Classification of businesses\n1.4 - Decisions on location\n1.5 - Business and the international economy \n1.6 - Government objectives and policies\n1.7 - External factors\n1.8 - What makes a business successful?"}, {"title": "Year 1 : People in business", "text": "Students will study people in organisations, focusing on their roles, relationships and management in business.\n2.1 - Internal and external communication\n2.2 - Recruitment and selection process\n2.3 - Training\n2.4 - Motivation and rewards\n2.5 - Organisation structure and employees"}, {"title": "Year 1 : Business finance", "text": "Students explore the use of accounting and financial information as an aid to decision making.\n3.1 - Business finance - sources\n3.2 - Cash flow forecasting\n3.3 - Costs and break-even analysis\n3.4 - Financial documents\n3.5 - Accounts analysis"}, {"title": "Year 2 : Marketing", "text": "Students focus on identifying and satisfying customer needs in a changing and competitive international environment.\n4.1 - Market research \n4.2 - The market\n4.3 - The marketing mix"}, {"title": "Year 2 : Business operations", "text": "Students examine the way organisations use and manage resources to produce goods and services.\n5.1 - Economies and diseconomies of scale\n5.2 - Production\n5.3 - Factors of production\n5.4 - Quality"}, {"title": "Year 2 : Revision", "text": "- Revision of all components of Edexcel iGCSE Business Studies Papers 1 & 2\n- Past Papers\n- Mock Exam"}]'::jsonb, 'Edexcel', true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'iGCSE';
  select id into sj from subjects where school_id = sch and lower(name) = lower('Geography');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'Geography', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'igcse/geography', '[{"title": "Coasts", "text": "In this unit, you will delve into the fascinating processes that shape distinctive coastal landforms. Additionally, you will examine the challenges confronting coastal ecosystems and explore detailed case studies of coastal management strategies implemented in both developed and developing/emerging countries."}, {"title": "Hazardous Environments", "text": "In this unit, you will explore the distinctive traits and distribution patterns of various natural hazards. You will delve into the ways in which these hazards are measured and their impact on society. Additionally, you will examine detailed case studies that illustrate the management of earthquakes in both developed and developing/emerging countries."}, {"title": "Urban Environments", "text": "In this unit, you will delve into the fascinating realm of urban environments, exploring their diverse trends, characteristics, and associated challenges. You will discover the unique difficulties facing contrasting urban landscapes and examine detailed case studies of both developed and developing/emerging countries, gaining a deep understanding of the complexities and nuances of urban life."}, {"title": "Economic Activity and Energy", "text": "In this unit, you will explore the dynamic fluctuations of economic activity across different time scales and geographic locations. The primary focus will be on examining the intricate correlation between population and resources, with an emphasis on completing detailed case studies on energy resource management in both developed and developing countries."}, {"title": "Development and Human Welfare", "text": "In this unit, you will explore a comprehensive overview of development and human welfare, including definitions, measurement techniques, and global development patterns. Delving deeper, you will also investigate the impact of disparities in development on individuals and societies. Additionally, you will examine a range of strategies that can be employed to address uneven levels of development and promote greater human welfare."}, {"title": "Revision", "text": "- Revision of all components of Edexcel iGCSE Geography Papers 1 & 2\n- Past Papers\n- Mock Exam"}]'::jsonb, 'Edexcel', true)
    on conflict (school_id, level_id, subject_id) do update set topics = excluded.topics, exam_board = excluded.exam_board, slug = excluded.slug, published = true; end if;
  select id into lv from levels where school_id = sch and name = 'iGCSE';
  select id into sj from subjects where school_id = sch and lower(name) = lower('History');
  if sj is null then insert into subjects (school_id, name, colour) values (sch, 'History', '#8494c2') returning id into sj; end if;
  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'igcse/history', '[{"title": "Germany: development of dictatorship, 1918–45", "text": "- The establishment of the Weimar Republic and its early problems\n- The recovery of Germany, 1924–29\n- The rise of Hitler and the Nazis to January 1933\n- Nazi Germany 1933–39\n- Germany and the occupied territories during the Second World War"}, {"title": "A divided union: civil rights in the USA, 1945–74", "text": "- The Red Scare and McCarthyism\n- Civil rights in the 1950s\n- The impact of civil rights protests, 1960–74\n- Other protest movements: students, women, anti–Vietnam\n- Nixon and Watergate"}, {"title": "Investigation: The USA, 1918–41", "text": "- The Roaring Twenties\n- Increased social tensions in the 1920s\n- The USA in Depression, 1929–33\n- Roosevelt and the New Deal, 1933–41\n- The Opposition to the New Deal"}, {"title": "Breadth Studies: Changes in medicine, c1848–c1948", "text": "- Progress in the mid19th century; Nightingale, Chadwick, Snow and Simpson\n- Discovery and development, 1860–75; Lister and Pasteur\n- Accelerating change, 1875–1905; Ehrlich, Koch and chemistry\n- Government action and war, 1905–20\n- Advances in medicine, surgery and public health 1920–48; the NHS"}, {"title": "Revision", "text": "- Revision of all components of Edexcel iGCSE History Papers 1 & 2\n- Past Papers\n- Mock Exam"}]'::jsonb, 'Edexcel', true)
