  if lv is not null then insert into course_pages (school_id, level_id, subject_id, slug, topics, exam_board, published) values (sch, lv, sj, 'igcse/maths-foundation', '[{"title": "Number", "text": "Use numerical skills in a purely mathematical way and in real-life situations."}, {"title": "Algebra", "text": "- Use letters as equivalent to numbers and as variables.\n- Understand the distinction between expressions, equations and formulae.\n- Use algebra to set up and solve problems.\n- Demonstrate manipulative skills.\n- Construct and use graphs."}, {"title": "Geometry", "text": "- Use properties of angles.\n- Understand a range of transformations.\n- Work within the metric system.\n- Understand ideas of space and shape.\n- Use ruler, compasses and protractor appropriately."}, {"title": "Statistics", "text": "- Understand basic ideas of statistical averages.\n- Use a range of statistical techniques.\n- Use basic ideas of probability."}, {"title": "Mathematical Reasoning", "text": "- Making deductions and drawing conclusions from mathematical information\n- Constructing chains of reasoning\n- Presenting arguments and proofs\n- Interpreting and communicating information accurately"}, {"title": "Revision", "text": "- Revision of all components of Edexcel iGCSE Maths Foundation Papers 1 & 2\n- Past Papers\n- Mock Exam"}]'::jsonb, 'Edexcel', true)
